"""Generated by `siliconforge isa gen`: assembler, golden model and timing checker for this ISA.

Standard library only. Do not edit; regenerate from isa.yaml."""
from __future__ import annotations

import ast
import json
import operator
import random
import re
from dataclasses import dataclass, field
from types import SimpleNamespace
from typing import Any

# ---------------------------------------------------------------- spec
class IsaError(ValueError):
    pass


@dataclass(frozen=True)
class Field_:
    letter: str
    lsb: int
    width: int

    @property
    def msb(self) -> int:
        return self.lsb + self.width - 1

    @property
    def mask(self) -> int:
        return ((1 << self.width) - 1) << self.lsb


@dataclass
class Operand:
    letter: str
    name: str
    kind: str  # uint | int | enum | label
    field: Field_
    enum: dict[str, int] | None = None
    doc: str = ""


@dataclass
class Instruction:
    name: str
    pattern: str
    mask: int  # bits the decoder checks
    match: int  # their required values
    operands: list[Operand]
    asm: str
    cycles: str  # expression over operand names, evaluated per execution
    flow: dict[str, Any]
    exec: str
    pin_event: bool = False
    doc: str = ""

    def operand(self, letter_or_name: str) -> Operand:
        for o in self.operands:
            if letter_or_name in (o.letter, o.name):
                return o
        raise KeyError(letter_or_name)


@dataclass
class StateVar:
    name: str
    width: int
    reset: int = 0


@dataclass
class IsaSpec:
    name: str
    word_bits: int
    state: list[StateVar]
    instructions: list[Instruction]
    enums: dict[str, dict[str, int]] = field(default_factory=dict)
    title: str = ""
    description: str = ""

    @property
    def max_addr(self) -> int:
        pc = next((s for s in self.state if s.name == "pc"), None)
        return (1 << pc.width) - 1 if pc else (1 << 16) - 1

    def by_name(self) -> dict[str, Instruction]:
        return {i.name: i for i in self.instructions}


def _parse_pattern(name: str, pattern: str, word_bits: int) -> tuple[int, int, dict[str, Field_]]:
    bits = re.sub(r"\s+", "", pattern)
    if len(bits) != word_bits:
        raise IsaError(f"{name}: encoding has {len(bits)} bits, expected {word_bits}")
    mask = match = 0
    fields: dict[str, list[int]] = {}
    for i, ch in enumerate(bits):
        pos = word_bits - 1 - i
        if ch in "01":
            mask |= 1 << pos
            match |= int(ch) << pos
        elif ch == "-":
            continue
        elif ch.isalpha():
            fields.setdefault(ch, []).append(pos)
        else:
            raise IsaError(f"{name}: invalid character '{ch}' in encoding")
    out = {}
    for letter, positions in fields.items():
        positions.sort()
        if positions != list(range(positions[0], positions[0] + len(positions))):
            raise IsaError(f"{name}: operand field '{letter}' is not contiguous")
        out[letter] = Field_(letter, positions[0], len(positions))
    return mask, match, out


def parse_spec(raw: dict[str, Any]) -> IsaSpec:
    if not isinstance(raw, dict):
        raise IsaError("isa.yaml must be a mapping")
    for key in ("name", "word_bits", "instructions"):
        if key not in raw:
            raise IsaError(f"missing '{key}'")
    word_bits = int(raw["word_bits"])
    enums = {k: {str(n): int(v) for n, v in vals.items()} for k, vals in (raw.get("enums") or {}).items()}
    state = [StateVar(str(n), int(w if not isinstance(w, dict) else w["width"]),
                      int(0 if not isinstance(w, dict) else w.get("reset", 0)))
             for n, w in (raw.get("state") or {}).items()]
    instrs: list[Instruction] = []
    seen: set[str] = set()
    for item in raw["instructions"]:
        name = str(item["name"]).lower()
        if name in seen:
            raise IsaError(f"duplicate instruction '{name}'")
        seen.add(name)
        mask, match, fields = _parse_pattern(name, item["encoding"], word_bits)
        declared = item.get("operands") or {}
        for letter in declared:
            if letter not in fields:
                raise IsaError(f"{name}: operand '{letter}' is declared but not in the encoding")
        operands = []
        for letter, fld in sorted(fields.items(), key=lambda kv: -kv[1].lsb):
            d = declared.get(letter)
            if d is None:
                raise IsaError(f"{name}: encoding field '{letter}' has no operand definition")
            kind = d.get("kind", "enum" if "enum" in d else "uint")
            enum = None
            if kind == "enum":
                ref = d.get("enum")
                enum = enums.get(ref) if isinstance(ref, str) else {str(k): int(v) for k, v in (ref or {}).items()}
                if not enum:
                    raise IsaError(f"{name}: enum for operand '{letter}' is empty or unknown")
                if max(enum.values()) >= 1 << fld.width:
                    raise IsaError(f"{name}: enum value does not fit in operand '{letter}' ({fld.width} bits)")
            elif kind not in ("uint", "int", "label"):
                raise IsaError(f"{name}: unknown operand kind '{kind}'")
            operands.append(Operand(letter, str(d.get("name", letter)), kind, fld, enum, str(d.get("doc", ""))))
        asm = str(item.get("asm", name))
        placeholders = set(re.findall(r"\{(\w+)\}", asm))
        names = {o.name for o in operands}
        if placeholders != names:
            raise IsaError(f"{name}: asm template uses {sorted(placeholders)} but operands are {sorted(names)}")
        flow = dict(item.get("flow") or {"kind": "seq"})
        if flow["kind"] not in ("seq", "jump", "cond", "halt", "stall"):
            raise IsaError(f"{name}: unknown flow kind '{flow['kind']}'")
        if flow["kind"] in ("jump", "cond") and flow.get("target") not in names:
            raise IsaError(f"{name}: flow target must name a label operand")
        instrs.append(Instruction(
            name=name, pattern=item["encoding"], mask=mask, match=match, operands=operands, asm=asm,
            cycles=str(item.get("cycles", 1)), flow=flow, exec=str(item.get("exec", "")),
            pin_event=bool(item.get("pin_event", False)), doc=str(item.get("doc", "")).strip(),
        ))
    # ambiguity: two encodings overlap when they agree on every bit both of them fix
    for i, a in enumerate(instrs):
        for b in instrs[i + 1:]:
            common = a.mask & b.mask
            if (a.match ^ b.match) & common == 0:
                raise IsaError(f"encodings of '{a.name}' and '{b.name}' overlap: some words decode as both")
    return IsaSpec(name=str(raw["name"]), word_bits=word_bits, state=state, instructions=instrs, enums=enums,
                   title=str(raw.get("title", raw["name"])), description=str(raw.get("description", "")).strip())

# ---------------------------------------------------------------- asm
_BINOPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.LShift: operator.lshift,
           ast.RShift: operator.rshift, ast.BitOr: operator.or_, ast.BitAnd: operator.and_, ast.BitXor: operator.xor}


class AsmError(Exception):
    def __init__(self, errors: list[str]) -> None:
        super().__init__("\n".join(errors))
        self.errors = errors


@dataclass
class Placed:
    addr: int
    word: int
    instr: Instruction | None
    operands: dict[str, int]
    line: int
    text: str
    bound: int | None = None
    expect: int | None = None


@dataclass
class Program:
    spec: IsaSpec
    words: dict[int, int]
    placed: list[Placed]
    labels: dict[str, int]
    consts: dict[str, int] = field(default_factory=dict)

    def image(self, depth: int | None = None, fill: int = 0) -> list[int]:
        size = depth or (max(self.words, default=-1) + 1)
        return [self.words.get(a, fill) for a in range(size)]

    def listing(self) -> str:
        width = (self.spec.word_bits + 3) // 4
        lines = []
        by_addr: dict[int, list[str]] = {}
        for n, a in self.labels.items():
            by_addr.setdefault(a, []).append(n)
        for p in self.placed:
            for lab in by_addr.get(p.addr, []):
                lines.append(f"{'':>6}  {'':<{width}}  {lab}:")
            lines.append(f"{p.addr:06x}  {p.word:0{width}x}  {p.text}")
        return "\n".join(lines)

    def hex(self, depth: int | None = None) -> str:
        width = (self.spec.word_bits + 3) // 4
        return "\n".join(f"{w:0{width}x}" for w in self.image(depth)) + "\n"


def _eval(expr: str, symbols: dict[str, int]) -> int:
    def walk(n: ast.AST) -> int:
        if isinstance(n, ast.Constant) and isinstance(n.value, int):
            return n.value
        if isinstance(n, ast.Name):
            if n.id in symbols:
                return symbols[n.id]
            raise KeyError(n.id)
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.USub, ast.UAdd, ast.Invert)):
            v = walk(n.operand)
            return -v if isinstance(n.op, ast.USub) else (~v if isinstance(n.op, ast.Invert) else v)
        if isinstance(n, ast.BinOp) and type(n.op) in _BINOPS:
            return _BINOPS[type(n.op)](walk(n.left), walk(n.right))
        raise ValueError(f"unsupported expression '{expr}'")

    return walk(ast.parse(expr.strip(), mode="eval").body)


def _norm(text: str) -> str:
    """Single spaces, and exactly ', ' after a comma, so templates and source compare equal."""
    return re.sub(r"\s+", " ", re.sub(r"\s*,\s*", ", ", text.strip()))


def _template_regex(instr: Instruction) -> re.Pattern[str]:
    rx = ""
    for part in re.split(r"(\{\w+\})", _norm(instr.asm)):
        m = re.fullmatch(r"\{(\w+)\}", part)
        rx += rf"(?P<{m.group(1)}>.+?)" if m else re.escape(part).replace(r"\ ", " ")
    return re.compile(rf"^{rx}$", re.IGNORECASE)


def _strip(line: str) -> str:
    for marker in ("//", ";", "#"):
        line = line.split(marker, 1)[0]
    return line.strip()


class Assembler:
    def __init__(self, spec: IsaSpec) -> None:
        self.spec = spec
        self.templates = [(i, _template_regex(i)) for i in spec.instructions]

    def assemble(self, source: str) -> Program:
        errors: list[str] = []
        consts: dict[str, int] = {}
        labels: dict[str, int] = {}
        stmts: list[tuple[int, int, str, str, int | None, int | None]] = []  # addr, line, kind, text, bound, expect
        addr, bound, expect = 0, None, None
        # ---- pass 1: addresses, labels, constants
        for n, raw in enumerate(source.splitlines(), 1):
            line = _strip(raw)
            while True:
                m = re.match(r"^([A-Za-z_]\w*)\s*:\s*(.*)$", line)
                if not m:
                    break
                if m.group(1) in labels:
                    errors.append(f"line {n}: label '{m.group(1)}' defined twice")
                labels[m.group(1)] = addr
                line = m.group(2).strip()
            if not line:
                continue
            if line.startswith("."):
                parts = line.split(None, 1)
                d, arg = parts[0].lower(), (parts[1] if len(parts) > 1 else "")
                try:
                    if d == ".org":
                        addr = _eval(arg, {**consts, **labels})
                    elif d == ".equ":
                        name, _, e = arg.partition(",")
                        consts[name.strip()] = _eval(e, {**consts, **labels})
                    elif d == ".bound":
                        bound = _eval(arg, consts)
                    elif d == ".expect":
                        expect = _eval(arg, consts)
                    elif d == ".word":
                        stmts.append((addr, n, "word", arg, None, None))
                        addr += 1
                    else:
                        errors.append(f"line {n}: unknown directive '{d}'")
                except (KeyError, ValueError, SyntaxError) as exc:
                    errors.append(f"line {n}: bad directive argument: {exc}")
                continue
            stmts.append((addr, n, "instr", line, bound, expect))
            bound, expect = None, None
            addr += 1
        symbols = {**consts, **labels}
        placed: list[Placed] = []
        words: dict[int, int] = {}
        # ---- pass 2: encode
        for a, n, kind, text, bnd, exp in stmts:
            try:
                p = self._encode_word(a, n, text, symbols) if kind == "word" else self._encode_instr(a, n, text, symbols)
                p.bound, p.expect = bnd, exp
            except (ValueError, KeyError) as exc:
                errors.append(f"line {n}: {exc.args[0] if isinstance(exc, KeyError) else exc}")
                continue
            if a > self.spec.max_addr:
                errors.append(f"line {n}: address {a} does not fit in the program counter")
            if a in words:
                errors.append(f"line {n}: address {a} is already used")
            words[a] = p.word
            placed.append(p)
        if errors:
            raise AsmError(errors)
        return Program(self.spec, words, placed, labels, consts)

    def _encode_word(self, addr: int, line: int, text: str, symbols: dict[str, int]) -> Placed:
        v = _eval(text, symbols)
        if not 0 <= v < 1 << self.spec.word_bits:
            raise ValueError(f".word value {v} does not fit in {self.spec.word_bits} bits")
        return Placed(addr, v, None, {}, line, f".word {text}")

    def _encode_instr(self, addr: int, line: int, text: str, symbols: dict[str, int]) -> Placed:
        text = _norm(text)
        matches = [(i, m) for i, rx in self.templates if (m := rx.match(text))]
        if not matches:
            known = sorted({i.asm.split()[0] for i in self.spec.instructions})
            raise ValueError(f"cannot parse '{text}' (instructions: {', '.join(known)})")
        if len(matches) > 1:
            raise ValueError(f"'{text}' is ambiguous: matches {', '.join(i.name for i, _ in matches)}")
        instr, m = matches[0]
        word = instr.match
        values: dict[str, int] = {}
        for op in instr.operands:
            raw = m.group(op.name).strip()
            if op.kind == "enum":
                assert op.enum is not None
                key = next((k for k in op.enum if k.lower() == raw.lower()), None)
                if key is None:
                    raise ValueError(f"'{raw}' is not valid for {op.name}; choose one of {', '.join(op.enum)}")
                v = op.enum[key]
            else:
                try:
                    v = _eval(raw, symbols)
                except KeyError as exc:
                    raise ValueError(f"unknown symbol {exc}") from exc
                except (ValueError, SyntaxError) as exc:
                    raise ValueError(f"bad value '{raw}' for {op.name}: {exc}") from exc
                if op.kind == "int":
                    lo, hi = -(1 << (op.field.width - 1)), (1 << (op.field.width - 1)) - 1
                    if not lo <= v <= hi:
                        raise ValueError(f"{op.name}={v} is outside {lo}..{hi}")
                    v &= (1 << op.field.width) - 1
                elif not 0 <= v < 1 << op.field.width:
                    raise ValueError(f"{op.name}={v} does not fit in {op.field.width} bits (0..{(1 << op.field.width) - 1})")
            values[op.name] = v
            word |= v << op.field.lsb
        return Placed(addr, word, instr, values, line, text)


# ------------------------------------------------------------------------------------------------ disassembly

def decode(spec: IsaSpec, word: int) -> tuple[Instruction, dict[str, int]] | None:
    """The one place that turns a word into (instruction, operand values); the model and tools all use it."""
    for instr in spec.instructions:
        if word & instr.mask == instr.match:
            vals = {}
            for op in instr.operands:
                raw = (word >> op.field.lsb) & ((1 << op.field.width) - 1)
                if op.kind == "int" and raw >> (op.field.width - 1):
                    raw -= 1 << op.field.width
                vals[op.name] = raw
            return instr, vals
    return None


def disassemble_word(spec: IsaSpec, word: int, labels: dict[int, str] | None = None) -> str:
    hit = decode(spec, word)
    if hit is None:
        return f".word 0x{word:0{(spec.word_bits + 3) // 4}x}"
    instr, vals = hit
    shown = {}
    for op in instr.operands:
        v = vals[op.name]
        if op.kind == "enum":
            assert op.enum is not None
            shown[op.name] = next((k for k, x in op.enum.items() if x == v), str(v))
        elif op.kind == "label" and labels and v in labels:
            shown[op.name] = labels[v]
        else:
            shown[op.name] = str(v)
    return instr.asm.format(**shown)


def disassemble(spec: IsaSpec, words: list[int]) -> str:
    targets: dict[int, str] = {}
    for w in words:
        hit = decode(spec, w)
        if hit:
            for op in hit[0].operands:
                if op.kind == "label":
                    targets.setdefault(hit[1][op.name], f"L{hit[1][op.name]}")
    lines = []
    for a, w in enumerate(words):
        if a in targets:
            lines.append(f"{targets[a]}:")
        lines.append(f"    {disassemble_word(spec, w, targets)}")
    return "\n".join(lines) + "\n"

# ---------------------------------------------------------------- model
class IllegalInstruction(Exception):
    def __init__(self, addr: int, word: int) -> None:
        super().__init__(f"illegal instruction 0x{word:x} at address {addr}")
        self.addr, self.word = addr, word


class State:
    """Architectural state with hardware-style fixed widths."""

    def __init__(self, spec: IsaSpec) -> None:
        object.__setattr__(self, "_spec", {v.name: v for v in spec.state})
        object.__setattr__(self, "_stall", False)
        self.reset()

    def reset(self) -> None:
        for v in self._spec.values():
            object.__setattr__(self, v.name, v.reset & ((1 << v.width) - 1))
        object.__setattr__(self, "_stall", False)

    def __setattr__(self, name: str, value: int) -> None:
        var = self._spec.get(name)
        if var is None:
            raise AttributeError(f"'{name}' is not architectural state (declared: {', '.join(self._spec)})")
        object.__setattr__(self, name, int(value) & ((1 << var.width) - 1))

    def snapshot(self) -> dict[str, int]:
        return {n: getattr(self, n) for n in self._spec}


@dataclass
class StepResult:
    addr: int
    word: int
    instr: Instruction
    operands: dict[str, int]
    cycles: int
    stalled: bool


class Machine:
    def __init__(self, spec: IsaSpec, program: Program | list[int], illegal: str = "error") -> None:
        self.spec = spec
        self.imem = program.image() if isinstance(program, Program) else list(program)
        self.s = State(spec)
        self.inputs: dict[str, int] = {}
        self.illegal = illegal  # error | halt | nop
        self.cycles = 0
        self.retired = 0
        self._compiled: dict[str, tuple[Any, Any]] = {}
        self._pc_mask = (1 << next(v.width for v in spec.state if v.name == "pc")) - 1

    def reset(self) -> None:
        self.s.reset()
        self.cycles = self.retired = 0

    @property
    def halted(self) -> bool:
        return bool(getattr(self.s, "halted", 0))

    def _code(self, instr: Instruction) -> tuple[Any, Any]:
        if instr.name not in self._compiled:
            self._compiled[instr.name] = (
                compile(instr.exec or "pass", f"<{instr.name}.exec>", "exec"),
                compile(instr.cycles, f"<{instr.name}.cycles>", "eval"),
            )
        return self._compiled[instr.name]

    def step(self) -> StepResult:
        pc = self.s.pc
        word = self.imem[pc] if pc < len(self.imem) else 0
        hit = decode(self.spec, word)
        if hit is None:
            if self.illegal == "error":
                raise IllegalInstruction(pc, word)
            if self.illegal == "halt" and "halted" in self.s._spec:
                self.s.halted = 1
            self.s.pc = pc + 1
            self.cycles += 1
            return StepResult(pc, word, self.spec.instructions[0], {}, 1, False)
        instr, ops = hit
        code, cycles_code = self._code(instr)
        object.__setattr__(self.s, "_stall", False)
        env: dict[str, Any] = {
            **ops,
            "s": self.s,
            "inp": SimpleNamespace(**{k: self.inputs.get(k, 0) for k in self.inputs}, get=lambda k, d=0: self.inputs.get(k, d)),
            "stall": lambda: object.__setattr__(self.s, "_stall", True),
            "mask": self._pc_mask,
        }
        self.s.pc = pc + 1  # pc points at the next instruction before the snippet runs, so a jump just assigns s.pc
        exec(code, {"__builtins__": {}}, env)  # noqa: S102 - spec-defined semantics, see module docstring
        stalled = bool(self.s._stall)
        if stalled:
            self.s.pc = pc  # repeat this instruction next cycle
            n = 1
        else:
            n = int(eval(cycles_code, {"__builtins__": {}}, env))  # noqa: S307
        self.cycles += n
        self.retired += 0 if stalled else 1
        return StepResult(pc, word, instr, ops, n, stalled)

    def run(self, max_steps: int = 100_000) -> int:
        """Run until the program halts or the step budget is spent; returns instructions retired."""
        for _ in range(max_steps):
            if self.halted:
                break
            self.step()
        return self.retired

# ---------------------------------------------------------------- randprog
_CORNER_BIAS = 0.3


def random_operand(op, rng: random.Random, length: int) -> int:
    if op.enum:
        return rng.choice(sorted(op.enum.values()))
    width = op.field.width
    top = (1 << width) - 1
    if op.kind == "label":
        return rng.randrange(max(1, min(length, top + 1)))
    if rng.random() < _CORNER_BIAS:
        return rng.choice([0, 1, top, max(0, top - 1)]) & top
    return rng.randrange(top + 1)


def random_word(instr: Instruction, rng: random.Random, length: int) -> int:
    word = instr.match
    for op in instr.operands:
        word |= random_operand(op, rng, length) << op.field.lsb
    return word


def random_program(spec: IsaSpec, rng: random.Random, length: int, weights: dict[str, float] | None = None,
                   forbid: frozenset[str] | set[str] = frozenset(), end_with: str | None = None) -> list[int]:
    """`length` valid instruction words; the last one is `end_with` (e.g. "halt") when given."""
    pool = [i for i in spec.instructions if i.name not in forbid]
    if not pool:
        raise ValueError("every instruction is forbidden")
    w = [float((weights or {}).get(i.name, 1.0)) for i in pool]
    words = [random_word(rng.choices(pool, w)[0], rng, length) for _ in range(length)]
    if end_with:
        words[-1] = random_word(spec.by_name()[end_with], rng, length)
    return words

# ---------------------------------------------------------------- timing
START = -1  # virtual source: the first pin event after reset


@dataclass
class Gap:
    src: int  # address of the earlier pin event (START for program entry)
    dst: int  # address of the later pin event
    min_cycles: int
    max_cycles: int | None  # None = unbounded

    @property
    def exact(self) -> bool:
        return self.max_cycles is not None and self.min_cycles == self.max_cycles


@dataclass
class TimingReport:
    static: list[Gap] = field(default_factory=list)
    trace: list[tuple[int, int, int]] = field(default_factory=list)  # (src addr, dst addr, measured cycles)
    problems: list[str] = field(default_factory=list)
    notes: list[str] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        return not self.problems

    def text(self) -> str:
        lines = []
        for g in self.static:
            src = "start" if g.src == START else f"@{g.src}"
            hi = "unbounded" if g.max_cycles is None else str(g.max_cycles)
            lines.append(f"static  {src:>6} -> @{g.dst}: {g.min_cycles}..{hi} cycles{'  (exact)' if g.exact else ''}")
        for s, d, c in self.trace[:20]:
            lines.append(f"trace   {'start' if s == START else f'@{s}':>6} -> @{d}: {c} cycles")
        lines += [f"note: {n}" for n in self.notes] + [f"PROBLEM: {p}" for p in self.problems]
        return "\n".join(lines)


def _cost(instr, ops) -> int | None:
    try:
        return int(eval(compile(instr.cycles, "<cycles>", "eval"), {"__builtins__": {}}, dict(ops)))  # noqa: S307
    except Exception:  # noqa: BLE001 - depends on run-time state, so it is not a static constant
        return None


def static_gaps(program: Program) -> TimingReport:
    spec = program.spec
    rep = TimingReport()
    nodes: dict[int, dict] = {}
    for p in program.placed:
        if p.instr is None:
            continue
        hit = decode(spec, p.word)
        assert hit is not None
        instr, ops = hit
        cost = _cost(instr, ops)
        if cost is None:
            rep.notes.append(f"@{p.addr} {instr.name}: cycle count depends on run-time state, so it is excluded from "
                             "static bounds (use the trace check)")
            cost = 1
        kind = instr.flow["kind"]
        succ: list[int] = []
        if kind in ("seq", "stall"):
            succ = [p.addr + 1]
        elif kind == "jump":
            succ = [ops[instr.flow["target"]]]
        elif kind == "cond":
            succ = [ops[instr.flow["target"]], p.addr + 1]
        nodes[p.addr] = {"cost": cost, "succ": succ, "pin": instr.pin_event, "bound": p.bound, "kind": kind,
                         "name": instr.name}
    sources = [START] + [a for a, n in nodes.items() if n["pin"]]
    entry = min(nodes, default=0)
    for src in sources:
        first = [entry] if src == START else nodes[src]["succ"]
        start_cost = 0 if src == START else nodes[src]["cost"]
        found, unbounded = _explore(nodes, first, start_cost)
        for dst, (lo, hi) in sorted(found.items()):
            rep.static.append(Gap(src, dst, int(lo), None if unbounded else int(hi)))
        if unbounded:
            rep.notes.append(f"{'start' if src == START else f'@{src}'}: a loop is not bounded, so the maximum gap is "
                             "open (add `.bound N` before the branch that closes the loop)")
    return rep


def _explore(nodes: dict[int, dict], first: list[int], start_cost: int) -> tuple[dict[int, list[int]], bool]:
    """All paths from `first` to the next pin events: {dst: [min, max]} and whether some loop was left unbounded."""
    found: dict[int, list[int]] = {}
    unbounded = False
    budget = 200_000
    stack = [(f, start_cost, 0, {}, {}) for f in first]  # addr, cycles so far, bounded takes so far, seen, takes per node
    while stack:
        addr, acc, total_takes, seen, takes = stack.pop()
        budget -= 1
        if budget < 0:
            return found, True
        n = nodes.get(addr)
        if n is None:
            continue  # ran off the end of the program
        if n["pin"]:
            lo_hi = found.setdefault(addr, [acc, acc])
            lo_hi[0], lo_hi[1] = min(lo_hi[0], acc), max(lo_hi[1], acc)
            continue
        if seen.get(addr) == total_takes:
            unbounded = True  # back here with no bounded branch taken in between: an open loop
            continue
        seen = {**seen, addr: total_takes}
        for i, nxt in enumerate(n["succ"]):
            if n["kind"] == "cond" and i == 0 and n["bound"] is not None:
                if takes.get(addr, 0) >= n["bound"]:
                    continue  # the pragma says this branch cannot be taken again
                stack.append((nxt, acc + n["cost"], total_takes + 1, seen, {**takes, addr: takes.get(addr, 0) + 1}))
            else:
                stack.append((nxt, acc + n["cost"], total_takes, seen, takes))
    return found, unbounded


def trace_gaps(program: Program, inputs: dict[str, int] | None = None, max_steps: int = 20_000,
               max_events: int = 64) -> list[tuple[int, int, int]]:
    """Measure real cycle gaps between pin events by running the golden model."""
    m = Machine(program.spec, program, illegal="halt")
    m.inputs = dict(inputs or {})
    out: list[tuple[int, int, int]] = []
    last_t, last_a = 0, START
    pins = {a for a, p in ((p.addr, p.instr) for p in program.placed) if p and p.pin_event}
    for _ in range(max_steps):
        if m.halted or len(out) >= max_events:
            break
        t = m.cycles
        pc = m.s.pc
        r = m.step()
        if pc in pins and not r.stalled:
            out.append((last_a, pc, t - last_t))
            last_t, last_a = t, pc
    return out


def check_timing(program: Program, inputs: dict[str, int] | None = None) -> TimingReport:
    rep = static_gaps(program)
    rep.trace = trace_gaps(program, inputs)
    expects = {p.addr: p.expect for p in program.placed if p.expect is not None}
    for dst, want in expects.items():
        measured = [c for _, d, c in rep.trace if d == dst]
        if not measured:
            rep.problems.append(f"@{dst}: .expect {want} but this pin event never ran in the trace")
        bad = [c for c in measured if c != want]
        if bad:
            rep.problems.append(f"@{dst}: expected {want} cycles after the previous pin event, measured {sorted(set(bad))}")
        static = [g for g in rep.static if g.dst == dst]
        if static and all(g.exact and g.min_cycles == want for g in static):
            rep.notes.append(f"@{dst}: {want} cycles is proven by the control-flow graph, not only observed")
        elif static and any(g.min_cycles > want or (g.max_cycles is not None and g.max_cycles < want) for g in static):
            rep.problems.append(f"@{dst}: .expect {want} is outside the static range "
                                + ", ".join(f"{g.min_cycles}..{g.max_cycles}" for g in static))
    return rep


SPEC_DICT = json.loads("{\"name\": \"pio16\", \"title\": \"PIO16\", \"description\": \"A deliberately small 16-bit pin engine used to demonstrate the ISA toolchain: it drives and reads eight pins with cycle-exact timing, has two 8-bit counters and a 5-bit program counter (32 instructions). It is a teaching spec, not a product; copy it as the starting point for your own.\\n\", \"word_bits\": 16, \"state\": {\"pc\": 5, \"x\": 8, \"y\": 8, \"pins\": 8, \"oe\": 8, \"halted\": 1}, \"instructions\": [{\"name\": \"nop\", \"encoding\": \"0000 0000 0000 0000\", \"doc\": \"Do nothing for one cycle.\", \"cycles\": 1}, {\"name\": \"ldx\", \"encoding\": \"0001 vvvvvvvv ----\", \"asm\": \"ldx {v}\", \"operands\": {\"v\": {\"name\": \"v\"}}, \"doc\": \"Load the X counter with an 8-bit constant.\", \"exec\": \"s.x = v\"}, {\"name\": \"ldy\", \"encoding\": \"0010 vvvvvvvv ----\", \"asm\": \"ldy {v}\", \"operands\": {\"v\": {\"name\": \"v\"}}, \"doc\": \"Load the Y counter with an 8-bit constant.\", \"exec\": \"s.y = v\"}, {\"name\": \"pins\", \"encoding\": \"0011 vvvvvvvv ----\", \"asm\": \"pins {v}\", \"operands\": {\"v\": {\"name\": \"v\"}}, \"pin_event\": true, \"doc\": \"Drive the eight output pins. This is a pin event for the timing checker.\", \"exec\": \"s.pins = v\"}, {\"name\": \"oe\", \"encoding\": \"0100 vvvvvvvv ----\", \"asm\": \"oe {v}\", \"operands\": {\"v\": {\"name\": \"v\"}}, \"pin_event\": true, \"doc\": \"Set the output-enable mask (1 = drive).\", \"exec\": \"s.oe = v\"}, {\"name\": \"delay\", \"encoding\": \"0101 nnnnnnnn ----\", \"asm\": \"delay {n}\", \"operands\": {\"n\": {\"name\": \"n\"}}, \"cycles\": \"1 + n\", \"doc\": \"Wait n extra cycles, so the instruction takes 1 + n cycles in total.\"}, {\"name\": \"jmp\", \"encoding\": \"0110 ---- --- ttttt\", \"asm\": \"jmp {t}\", \"operands\": {\"t\": {\"name\": \"t\", \"kind\": \"label\"}}, \"flow\": {\"kind\": \"jump\", \"target\": \"t\"}, \"doc\": \"Jump to an address.\", \"exec\": \"s.pc = t\"}, {\"name\": \"djnz\", \"encoding\": \"0111 ---- --- ttttt\", \"asm\": \"djnz {t}\", \"operands\": {\"t\": {\"name\": \"t\", \"kind\": \"label\"}}, \"flow\": {\"kind\": \"cond\", \"target\": \"t\"}, \"doc\": \"Decrement X, then jump if X is not zero. A loop that uses it needs `.bound` for the timing checker.\", \"exec\": \"s.x = s.x - 1\\nif s.x != 0:\\n    s.pc = t\\n\"}, {\"name\": \"jpin\", \"encoding\": \"1000 -ppp --- ttttt\", \"asm\": \"jpin {p}, {t}\", \"operands\": {\"p\": {\"name\": \"p\"}, \"t\": {\"name\": \"t\", \"kind\": \"label\"}}, \"flow\": {\"kind\": \"cond\", \"target\": \"t\"}, \"doc\": \"Jump if input pin p is high.\", \"exec\": \"if (inp.get(\\\"pins\\\") >> p) & 1:\\n    s.pc = t\\n\"}, {\"name\": \"halt\", \"encoding\": \"1111 0000 0000 0000\", \"flow\": {\"kind\": \"halt\"}, \"doc\": \"Stop the engine.\", \"exec\": \"s.halted = 1\"}]}")


def load() -> IsaSpec:
    return parse_spec(SPEC_DICT)


def assemble(source: str) -> Program:
    return Assembler(load()).assemble(source)
